def solve(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                # BFS flood fill
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if 0 <= cr < rows and 0 <= cc < cols and grid[cr][cc] == 1:
                        grid[cr][cc] = 0
                        stack.append((cr+1, cc))
                        stack.append((cr-1, cc))
                        stack.append((cr, cc+1))
                        stack.append((cr, cc-1))
    return count

