def solve(s):
    n = len(s)
    if n < 2:
        return s
    start, maxlen = 0, 1
    for i in range(n):
        # odd length centered at i
        l = r = i
        while l >= 0 and r < n and s[l] == s[r]:
            if r - l + 1 > maxlen:
                start = l
                maxlen = r - l + 1
            l -= 1
            r += 1
        # even length centered at i,i+1
        l, r = i, i+1
        while l >= 0 and r < n and s[l] == s[r]:
            if r - l + 1 > maxlen:
                start = l
                maxlen = r - l + 1
            l -= 1
            r += 1
    return s[start:start+maxlen]

