    if amount == 0:
        return 0
    coins = sorted(set(coins), reverse=True)
    # BFS for shortest path
    from collections import deque
    visited = {0}
    queue = deque([(0, 0)])
    while queue:
        current, count = queue.popleft()
        for c in coins:
            nxt = current + c
            if nxt == amount:
                return count + 1
            if nxt > amount:
                continue
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, count + 1))
    return -1
