            M+=12; Y-=1
        K=Y%100; J=Y//100
        h=(D+13*(M+1)//5+K+K//4+J//4+5*J)%7
        names={0:'Saturday',1:'Sunday',2:'Monday',3:'Tuesday',4:'Wednesday',5:'Thursday',6:'Friday'}
        return names[h]
def solve(*args,**kwargs):
    # support solve(y,m,d), solve((y,m,d)), solve([y,m,d])
    if kwargs:
        y=kwargs.get('year',kwargs.get('y',kwargs.get('Y')))
        m=kwargs.get('month',kwargs.get('m'))
        d=kwargs.get('day',kwargs.get('d'))
        if y is not None and m is not None and d is not None:
            return _dow(y,m,d)
    if len(args)==3:
        return _dow(args[0],args[1],args[2])
    if len(args)==1:
