def solve(matrix):
    # Empty matrix => 1
    if not matrix:
        return 1
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    # Make a deep copy (we'll mutate)
    A = [row[:] for row in matrix]
    sign = 1
    det = 1
    for col in range(n):
        # Find pivot
        pivot = -1
        for row in range(col, n):
            if A[row][col] != 0:
                pivot = row
                break
        if pivot == -1:
            return 0
        if pivot != col:
            A[pivot], A[col] = A[col], A[pivot]
            sign = -sign
        det *= A[col][col]
        pivot_val = A[col][col]
        # Eliminate below
        for row in range(col + 1, n):
            if A[row][col] != 0:
                factor = A[row][col] / pivot_val
                for c in range(col, n):
                    A[row][c] -= factor * A[col][c]
    return int(sign * det)

